INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(1, 7, 'Nitrogênio', 'N', 14.007, '2 2 3', 3.04, 1.2506, -210, -196, 'Na área química, o N2 é usado, entre outras coisas, para melhorar o rendimento de algumas reações. Também evitar a oxidação, decomposição ou hidrólise de reagentes ou produtos. Na indústria alimentar, ele pode ser usado para inibir o desenvolvimento de bolores e insetos.', 'A imagem mostra o nitrogênio líquido', '', 15, 2);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(2, 15, 'Fósforo', 'P', 30.974, '2 8 5 ', 2.19, 1823, 44, 280, 'Nos palitos de fósforo (lembrando que o fósforo está contido nas caixas e não no palito); Na composição de ligas metálicas; Na indústria de fertilizantes; Na composição dos cremes e géis dentais; Para prevenir corrosão.', 'Pó de fósforo de coloração vermelha', '', 15, 3);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(3, 33, 'Arsênio', 'As', 74.922, '2 8 18 5', 2.18, 5727, 817, 887, 'Conservante de couro e madeira (arseniato de cobre e crômio), uso que representa, segundo algumas estimativas, cerca de 70% do seu consumo mundial.', 'Pedra de arsênio', '', 15, 4);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(4, 51, 'Antimônio', 'Sb', 121.76, '2 8 18 18 5', 2.05, 6697, 630, 1577, 'É utilizado em ligas para que sejam atingidas determinadas propriedades físicas. Além de ser adicionado (sob formas variadas de compostos) a cerâmicas e esmaltes para aumento de resistência pirofórica, na borracha para o processo de vulcanização e na fabricação de fogos de artifício.\r\nTambém apresenta funcionalidade na produção de baterias e acumuladores, revestimento de cabos, almofadas, vidros e semicondutores (para a construção de diodos).', 'Cristal de antimônio de coloração denominada cinza prateado lustroso', '', 15, 5);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(5, 83, 'Bismuto', 'Bi', 208.98, '2 8 18 32 18 5', 2.02, 9780, 271, 1560, 'Usado como componente de produtos médicos, terapêuticos e produtos cosméticos. Também pode ser usado para dar brilho ao esmalte, na produção de ferros maleáveis, ímãs permanentes fortes formados da liga de bismuto e em usinas nucleares como suporte para o combustível.', 'Cristal de bismuto com uma leve camada de oxidação', '', 15, 6);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(6, 115, 'Moscóvio', 'Mc', 290, '2 8 18 32 32 18 5', 0, 11000, 430, 1100, 'Não existem aplicações.', 'Arte conceitual do elemento Moscovio', '', 15, 7);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(7, 10, 'Neônio', 'Ne', 20.18, '2 8', 0, 0.8999, -249, -246, 'Gás neônio encontra-se presente nas lâmpadas fluorescentes; A mistura de neônio e argônio dá origem à válvulas para raios-X; As pequenas lâmpadas de sinalização usadas em aparelhos elétricos e eletrônicos contêm gás Neônio em sua composição; O Neônio é usado na forma líquida nos sensores ultrassensíveis de infravermelho.', 'Neônio sendo usado em uma lâmpada fluorescente', '', 18, 2);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(8, 3, 'Lítio', 'Li', 6.939, '2 1', 0.98, 0.53, 180, 1336, 'Elaboração de esmalte para cerâmica.', 'Metal de Lítio', '', 1, 2);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(9, 11, 'Sódio', 'Na', 22.99, '2 8 1', 0.93, 0.97, 98, 892, 'Uso culinário.', 'Metal de Sódio', '', 1, 4),
(10, 19, 'Potássio', 'K', 39.098, '2 8 8 1', 0.82, 0.86, 64, 774, 'Fertilizante, pólvora.', 'Metal de Potássio', '', 1, 4);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(11, 37, 'Rubídio', 'Rb', 85.468, '2 8 18 8 1', 0.82, 1.53, 39, 688, 'Indústria de vidros, sedativo.', 'Metal de Rubídio', '', 1, 5),
(12, 55, 'Césio', 'Cs', 132.91, '2 8 18 18 8 1', 0.79, 1.87, 28, 705, 'Usado em detectores de raios infravermelhos.', 'Metal de Césio', '', 1, 6);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(13, 87, 'Frâncio', 'Fr', 223, '2 8 18 32 18 8 1', 0.79, 0, 27, 680, 'Não são conhecidas aplicações.', 'Metal de Frâncio', '', 1, 7);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(14, 54, 'Xenônio', 'Xe', 131.29, '2 8 18 18 8', 2.6, 5.9, -112, -107, 'Usado em laser ultravioleta, lâmpadas de bronzeamento artificial.', 'Lâmpada de bronzeamento', '', 18, 5);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(15, 4, 'Berílio', 'Be', 9.012182, '2 2', 1.57, 1848, 1560, 2744, 'Produção de ligas metálicas; Moderador de nêutrons em reatores nucleares; recentemente era empregado composto de berílio em tubos fluorescentes; é utilizado para filtrar radiação visível nos diagnósticos com raio x; é empregado na construção de giroscópios, equipamentos de informática, molas de relógios, guias de projeteis, foguetes e instrumentais diversos.', 'Pedra que contém fragmentos de berílio', '', 2, 2);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(16, 12, 'Magnésio', 'Mg', 24.305, '2 8 2', 1.31, 1738, 923, 1363, 'Compostos de Mg são usados como material refratário em fornos para a produção de ferro e aço, metais não ferrosos, cristais e cimento; Compostos de magnésio são também aplicados na agricultura; O Mg é elemento de liga com o alumínio, para a produção de recipientes de bebidas, componentes de automóveis como aros de roda e maquinarias diversas. ', 'Pedra de magnésio', '', 2, 3);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(17, 20, 'Cálcio', 'Ca', 40.078, '2 8 8 2', 1, 1550, 1115, 1757, 'Ajuda na produção de líquido linfático; essencial para a transmissão nervosa, coagulação do sangue e contrações musculares; atua também na respiração muscular e na manutenção dos ossos.', 'Pedra de cálcio', '', 2, 4);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(18, 38, 'Estrôncio', 'Sr', 87.62, '2 8 18 8 2', 0.95, 2630, 1050, 1655, 'Uma das aplicações do estrôncio é em cristais para tubos de raios catódicos de televisores em cores. Além disso, é usado para a pirotecnia e produção de imãs de ferrita.', 'Celestina - material composto de sulfato de estrôncio ', '', 2, 5);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(19, 56, 'Bário', 'Ba', 137.327, '2 8 18 18 8 2', 0.89, 3510, 1000, 2170, 'O Bário é usado principalmente em velas de ignição, tubos de vácuo, foguetes pirotécnicos, e em lâmpadas fluorescentes.', 'Pedra que contém fragmentos de bário', '', 2, 6);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(20, 88, 'Rádio', 'Ra', 226, '2 8 18 32 18 8 2', 0.89, 5500, 973, 2010, 'Foi usado como tinta luminescente em mostradores de relógios e instrumentos de medidas. Este uso foi interrompido na década de 30. Grande maioria das pessoas que tem câncer necessita do medicamento à base desse metal.', 'Amostra do rádio brilhando no escuro', '', 2, 7),
(21, 86, 'Radônio', 'Rn', 222, '2 8 18 32 18 8', 2.2, 9.73, 202, 211.3, 'Amostras concentradas do produto são usadas em radioterapia e radiografia. Também vem sendo empregado em pesquisas hidrológicas.', 'Pedra de granito(fonte de radônio)', '', 18, 6);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(22, 5, 'Boro', 'B', 10.811, '2 3', 2.04, 2.34, 2573, 3931, 'Produção do bórax e do ácido bórico.', 'É um metal de cor marrom ou preta e com formato aleatório, normalmente ponteagudo.', '', 13, 2);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(23, 13, 'Alumínio', 'Al', 26.982, '2 8 3', 1.61, 2.34, 2573, 2792, 'Indústria, produção de ferramentas, usado na prodção de energia.', 'É um metal cinza prateado, que também é útil na produção de diversas coisas.', '', 13, 3);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(24, 31, 'Gálio', 'Ga', 69.723, '2 8 18 3', 1.81, 5.91, 302.93, 2676, 'A principal aplicação do gálio, na forma de arsenieto de gálio, é na construção de circuitos integrados e dispositivos optoeletrônicos como diodos de laser e diodos LED.', 'Em temperatura ambiente é um metal branco prateado, porém em temperaturas acimas da ambiente pode-se encontra-lo no estado liquido.', '', 13, 4);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(25, 49, 'Índio', 'In', 114.818, '2 8 18 18 3', 1.78, 7310, 429.7485, 2345, 'Foi empregado durante a Segunda Guerra Mundial como revestimento em motores de alto rendimento de aviões. Depois da guerra foi destinado a novas aplicações: em ligas metálicas, em soldas e na indústria eletrônica.', 'É um metal cinza prateado lustroso, muito maleável e fundível.', '', 13, 5);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(26, 81, 'Tálio', 'Tl', 2043.833, '2 8 18 32 18 3', 1.62, 11.85, 576.6, 1730, 'Setor de inseticidas e venenos para roedores.', 'É um metal branco prateado, muito mole e maleável.', '', 13, 6);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(27, 1, 'Hidrogênio', 'H', 1.008, '1', 2.2, 0.0706, 14.025, 20.268, 'Petróleo e química.', 'É incolor e também é o elemento mais simples do universo.', '', 1, 1),
(28, 113, 'Nihonio', 'Nh', 286, '2 8 18 32 32 18 3', 0, 16, 700, 1400, 'Não existem aplicações.', 'É um metal sintético obtido a partir da desintegração do elemento Moscovita. 	', '', 13, 7);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(29, 6, 'Carbono', 'C', 12.0107, '2 4', 2.55, 2267, 3550, 4289, 'Diamante, grafite para lápis e obtenção de plásticos.', 'Barras de Aço Carbono, é muito usado na metalurgica pela seu grande grau de dureza.', '', 14, 2),
(30, 14, 'Silício', 'Si', 28.0855, '2 8 4', 1.9, 2330, 1414, 3265, 'É utilizado para a produção de ligas metálicas, na preparação de silicones, na indústria cerâmica e, por ser um material semicondutor muito abundante, tem um interesse muito especial na indústria eletrônica e microeletrônica, como material básico para a produção de transistores para chips, células solares e em diversas variedades de circuitos eletrônicos.', ' Minério em pó, utilizado em ligas metálicas, silicone e principalmente transistores e chips.', '', 14, 3);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(31, 32, 'Germânio', 'Ge', 72.64, '2 8 18 4', 2.01, 5323, 938.25, 2833, 'Fibra óptica, Radares, amplificadores de guitarras elétricas e sistemas de visão noturna.', ' Minério em estado sólido, utilizado equipamentos de visão noturna pela sua condução elétrica.', '', 14, 4);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(32, 50, 'Estanho', 'Sn', 7310, '2 8 18 18 4', 1.96, 118.71, 231.93, 2602, 'O estanho liga-se prontamente com o ferro, e foi muito usado na indústria automotiva para revestimento e acabamento da lataria. O estanho que faz uma ótima liga com chumbo é usado como revestimento misturado ao zinco no aço para impedir a corrosão e evitar a eletrólise. O estanho também é muito usado em telhas, correntes e âncoras. Os recipientes de aço blindados com estanho (folhas de flandres) são usados extensivamente para a conservação de alimentos, e desta forma é um grande mercado para o estanho metálico.', ' Em fios para solda, metal usado para soldar placas de circuitos.', '', 14, 5),
(33, 82, 'Chumbo', 'Pb', 207.2, '2 8 18 32 18 4', 2.33, 11340, 327.46, 1749, 'O mais amplo uso do chumbo é na fabricação de acumuladores. Outras aplicações importantes são na fabricação de forros para cabos, elemento de construção civil, pigmentos, soldas suaves e munições.', 'Chumbada para pesca, útil pelo seu peso mesmo sendo pequeno.', '', 14, 6);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(34, 114, 'Flevório', 'Fl', 289, '2 8 18 32 18 4', 0, 22000, 0, 0, 'Atualmente só ocorrem pesquisas.', ' Elemento feito apenas em acelerador de particulas.', '', 14, 7);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(35, 114, 'Flevório', 'Fl', 289, '2 8 18 32 32 18 4', 0, 22000, 0, 0, 'Atualmente só ocorrem pesquisas.', ' Elemento feito apenas em acelerador de particulas.', '', 14, 7);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(36, 8, 'Oxigênio', 'O', 16, '2 6', 3.44, 1.429, -218.4, -182.8, 'Remoção do excesso de carbono presente no aço; Enriquecimento do ar puro para uso em hospitais; Utilizado em soldas de metais; Participação em reações químicas para a produção de diversas substâncias; Comburente das combustões (queima); Utilizado na fabricação do metanol; Utilizado na propulsão (lançamento) de foguetes, entre outras inúmeras aplicações.', 'Linhas espectrais do oxigênio.', '', 16, 2),
(37, 16, 'Enxofre', 'S', 32.07, '2 8 6', 2.58, 1960, 115.2, 444.6, 'Fabricação de ácido sulfúrico; Fabricação de pólvora; Fabricação de adubos; Fabricação de defensivos agrícolas; Vulcanização da borracha; Produção de fertilizantes; Está presente na composição de todos os sulfatos, sulfitos e sulfetos; Na forma de sulfato, pode ser utilizado como medicamento laxante, bactericida, fungicida, produção de suplementos para plantas, produção de alguns ácidos inorgânicos etc.; Na forma de sulfito, participa da produção de conservantes e como branqueador de papéis.', 'Enxofre pulverizado', '', 16, 3);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(38, 34, 'Selênio', 'Se', 78.96, '2 8 18 6', 2.55, 4.81, 220.8, 684.8, 'O selênio é utilizado como semicondutor, em células solares, em televisores, em copiadoras, xampu anti-caspa e como pigmento vermelho para coloração de vidro.', 'Uma pequena pizza de selênio', '', 16, 4);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(39, 52, 'Telúrio', 'Te', 127.6, '2 8 18 18 6', 2.1, 6.26, 449.5, 987.8, 'É adicionado a ligas ferrosas (incluindo-se o aço) para melhorar suas propriedades mecânicas; Junto ao chumbo e cobre, é aplicado em trabalhos de soldadura e em equipamentos químicos; Pode ser adicionado a borracha de forma a aumentar sua resistência ao tempo e ao calor; É utilizado como um dos componentes antidetonantes da gasolina; Junto ao bismuto, é utilizado em dispositivos termoelétricos.', 'Pedaços do metal telúrio.', '', 16, 5);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(40, 84, 'Polônio', 'Po', 209, '2 8 18 32 18 6', 2, 91.96, 253.8, 962, 'Pesquisa-se o uso como emissor de radiação alfa em fontes termelétricas de baixo peso, para satélites espaciais; Pode ser misturado ou ligado com berílio para formar uma fonte de nêutrons; Tem sido usado em dispositivos para eliminar cargas eletrostáticas em processos industriais mas fontes de radiação beta são mais comuns e menos perigosas.', 'Penchblenda, minério do qual é possível extrair 0,1 mg de polônio.', '', 16, 6);
INSERT INTO `elementos` (`idElemento`, `numeroAtomico`, `nome`, `simbolo`, `massa`, `distEletronica`, `eletronegatividade`, `densidade`, `pFusao`, `pEbulicao`, `aplicacoes`, `descImagem`, `img64`, `grupo`, `periodo`) VALUES
(41, 18, 'Argônio', 'Ar', 39.95, '2 8 8', 0, 1.784, -189.34, -185.84, 'Laser para medicina oftalmológica, que o utiliza no diagnóstico e tratamento de doenças oculares; Agente para proporcionar atmosferas inertes para soldagem de estruturas metálicas e na cristalização de silício e germânio para fabricação de semicondutores e dispositivos fotovoltaicos; Na fabricação de lâmpadas de iluminação comum para impedir que o filamento seja oxidado e em lâmpadas conhecidas como neon, em virtude de sua luz que é emitida quando este é submetido a luz infravermelha; Isolante, preenchendo os vazios entre vidros duplos e triplos em virtude de sua baixa condutividade térmica.', 'Argônio Gasoso sob luz infravermelha', '', 18, 3),
(42, 9, 'Flúor', 'F', 18.9984032, '9', 3.98, 1.696, -219.62, -188.1, 'Pastas de dente.', ' Pasta de dente', '', 17, 2),
